--
-- Name: b3_check_object(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.b3_check_object(kind text, object_id uuid, revision_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE actual_space uuid; registered_space uuid; expected jsonb; indexed jsonb;
BEGIN
 CASE kind
 WHEN 'block' THEN SELECT r.space_id INTO actual_space FROM public.block_revision r WHERE r.block_id=object_id AND r.id=revision_id;
 WHEN 'relation' THEN SELECT r.space_id INTO actual_space FROM public.relation_revision r WHERE r.relation_id=object_id AND r.id=revision_id;
 WHEN 'relation_review' THEN SELECT r.space_id INTO actual_space FROM public.relation_review r WHERE r.relation_revision_id=object_id AND r.id=revision_id;
 WHEN 'epistemic_review' THEN SELECT r.space_id INTO actual_space FROM public.epistemic_review r WHERE r.stream_id=object_id AND r.id=revision_id;
 ELSE RAISE EXCEPTION 'invalid source kind' USING ERRCODE='23514';
 END CASE;
 SELECT r.space_id INTO registered_space FROM public.reference_object r
  WHERE r.kind=b3_check_object.kind AND r.object_id=b3_check_object.object_id AND r.revision_id=b3_check_object.revision_id;
 IF actual_space IS NULL OR registered_space IS DISTINCT FROM actual_space THEN
  RAISE EXCEPTION 'registry identity or space mismatch' USING ERRCODE='23514';
 END IF;
 SELECT coalesce(jsonb_agg(value||jsonb_build_object('position',ordinality-1) ORDER BY ordinality),'[]') INTO expected
  FROM jsonb_array_elements(public.b3_expected_dependencies(kind,object_id,revision_id)) WITH ORDINALITY;
 SELECT coalesce(jsonb_agg(jsonb_build_object('position',d.position,'role',d.role,
  'target',jsonb_build_object('kind',d.target_kind,'object_id',d.target_object_id,'revision_id',d.target_revision_id)) ORDER BY d.position),'[]')
  INTO indexed FROM public.reference_dependency d
  WHERE d.source_kind=kind AND d.source_object_id=object_id AND d.source_revision_id=revision_id;
 IF indexed IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'dependency index differs from immutable payload' USING ERRCODE='23514';
 END IF;
END $$;


ALTER FUNCTION public.b3_check_object(kind text, object_id uuid, revision_id uuid) OWNER TO learning_admin;

--
-- Name: b3_check_reading_evidence(uuid); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.b3_check_reading_evidence(view_revision uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v record; selections jsonb; reviews jsonb;
BEGIN
 SELECT * INTO STRICT v FROM public.reading_view_revision WHERE id=view_revision;
 SELECT coalesce(jsonb_agg(jsonb_build_object('relation',jsonb_build_object('relation_id',s.relation_id,'revision_id',s.relation_revision_id),
  'review',CASE WHEN s.review_id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object('relation',jsonb_build_object('relation_id',s.relation_id,'revision_id',s.relation_revision_id),'review_id',s.review_id) END) ORDER BY s.position),'[]')
 INTO selections FROM public.reading_relation_selection s WHERE s.view_revision_id=view_revision;
 SELECT coalesce(jsonb_agg(jsonb_build_object('stream_id',s.stream_id,'review_id',s.review_id) ORDER BY s.position),'[]')
 INTO reviews FROM public.reading_epistemic_selection s WHERE s.view_revision_id=view_revision;
 IF v.contract_version=1 THEN
  IF selections<>'[]'::jsonb OR reviews<>'[]'::jsonb THEN RAISE EXCEPTION 'v1 reading has evidence' USING ERRCODE='23514'; END IF;
 ELSE
  PERFORM public.b3_shape(v.evidence,ARRAY['selections','epistemic_reviews']);
  PERFORM public.b3_selections(v.evidence->'selections');
  IF v.evidence IS DISTINCT FROM jsonb_build_object('selections',selections,'epistemic_reviews',reviews) THEN
   RAISE EXCEPTION 'reading evidence index mismatch' USING ERRCODE='23514';
  END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM public.reading_relation_selection s JOIN public.relation r ON r.id=s.relation_id
   WHERE s.view_revision_id=view_revision AND r.overlay_id IS NOT NULL AND r.overlay_id<>v.overlay_id)
 OR EXISTS(SELECT 1 FROM public.reading_epistemic_selection s JOIN public.epistemic_stream e ON e.id=s.stream_id
   WHERE s.view_revision_id=view_revision AND e.overlay_id IS NOT NULL AND e.overlay_id<>v.overlay_id)
 OR EXISTS(SELECT 1 FROM (SELECT position,row_number() OVER(ORDER BY position)-1 AS expected FROM public.reading_relation_selection WHERE view_revision_id=view_revision) p WHERE position<>expected)
 OR EXISTS(SELECT 1 FROM (SELECT position,row_number() OVER(ORDER BY position)-1 AS expected FROM public.reading_epistemic_selection WHERE view_revision_id=view_revision) p WHERE position<>expected)
 THEN RAISE EXCEPTION 'invalid reading evidence scope or positions' USING ERRCODE='23514'; END IF;
END $$;


ALTER FUNCTION public.b3_check_reading_evidence(view_revision uuid) OWNER TO learning_admin;

