--
-- Name: b3_expected_dependencies(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.b3_expected_dependencies(kind text, object_id uuid, revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE result jsonb:='[]'; row_data record; reference jsonb;
BEGIN
 CASE kind
 WHEN 'block' THEN
  SELECT r.contract_version,r.content INTO STRICT row_data FROM public.block_revision r
   WHERE r.block_id=object_id AND r.id=revision_id;
  RETURN public.b3_content_dependencies(row_data.contract_version,row_data.content);
 WHEN 'relation' THEN
  SELECT * INTO STRICT row_data FROM public.relation_revision r WHERE r.relation_id=object_id AND r.id=revision_id;
  result:=public.b3_edge('target',public.b3_reference(jsonb_build_object('block_id',row_data.from_block_id,'revision_id',row_data.from_revision_id),'block'))
   ||public.b3_edge('target',public.b3_reference(jsonb_build_object('block_id',row_data.to_block_id,'revision_id',row_data.to_revision_id),'block'));
 WHEN 'relation_review' THEN
  SELECT * INTO STRICT row_data FROM public.relation_review r WHERE r.relation_revision_id=object_id AND r.id=revision_id;
  result:=public.b3_edge('target',public.b3_reference(jsonb_build_object('relation_id',row_data.relation_id,'revision_id',row_data.relation_revision_id),'relation'));
 WHEN 'epistemic_review' THEN
  SELECT r.*,s.target_block_id,s.target_revision_id INTO STRICT row_data FROM public.epistemic_review r
   JOIN public.epistemic_stream s ON s.id=r.stream_id WHERE r.stream_id=object_id AND r.id=revision_id;
  result:=public.b3_edge('target',public.b3_reference(jsonb_build_object('block_id',row_data.target_block_id,'revision_id',row_data.target_revision_id),'block'))
   ||public.b3_selections(row_data.relations);
  IF jsonb_typeof(row_data.evidence) IS DISTINCT FROM 'array' OR jsonb_array_length(row_data.evidence)>256 THEN
   RAISE EXCEPTION 'invalid review evidence' USING ERRCODE='23514';
  END IF;
  FOR reference IN SELECT jsonb_array_elements(row_data.evidence) LOOP
   result:=result||public.b3_edge('basis',public.b3_reference(reference,'block'));
  END LOOP;
 ELSE RAISE EXCEPTION 'invalid source kind' USING ERRCODE='23514';
 END CASE;
 RETURN result;
EXCEPTION WHEN no_data_found THEN
 RAISE EXCEPTION 'registry has no matching immutable object' USING ERRCODE='23514';
END $$;


ALTER FUNCTION public.b3_expected_dependencies(kind text, object_id uuid, revision_id uuid) OWNER TO learning_admin;

--
-- Name: b3_lineage_complete(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.b3_lineage_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE op uuid; o record; n integer; last_position integer;
BEGIN
 IF TG_TABLE_NAME='lineage_operation' THEN op:=NEW.id; ELSE op:=NEW.operation_id; END IF;
 SELECT * INTO STRICT o FROM public.lineage_operation WHERE id=op;
 SELECT count(*),max(position) INTO n,last_position FROM public.lineage_input WHERE operation_id=op;
 IF n<>o.input_count OR last_position<>n-1 THEN
  RAISE EXCEPTION 'incomplete lineage inputs' USING ERRCODE='23514'; END IF;
 SELECT count(*),max(position) INTO n,last_position FROM public.lineage_output WHERE operation_id=op;
 IF n<>o.output_count OR last_position<>n-1 THEN
  RAISE EXCEPTION 'incomplete lineage outputs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.lineage_input i JOIN public.lineage_output r USING(operation_id,block_id) WHERE i.operation_id=op)
 THEN RAISE EXCEPTION 'lineage output reuses input identity' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.lineage_receipt r JOIN public.request_key k USING(actor_id,request_id)
   WHERE r.operation_id=op AND r.actor_id=o.author_id AND k.operation='lineage_apply' AND k.request_sha256=r.request_sha256)
 THEN RAISE EXCEPTION 'missing or mismatched lineage receipt' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION public.b3_lineage_complete() OWNER TO learning_admin;

--
-- Name: b3_lineage_new_member(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.b3_lineage_new_member() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE current_xid text := (pg_current_xact_id()::text::numeric % 4294967296)::text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.lineage_operation o WHERE o.id=NEW.operation_id AND o.xmin::text=current_xid)
 THEN RAISE EXCEPTION 'lineage operation must be created atomically' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='lineage_output' THEN
  IF NOT EXISTS(SELECT 1 FROM public.block b JOIN public.block_revision r ON r.block_id=b.id AND r.id=b.head_revision_id
    JOIN public.lineage_operation o ON o.id=NEW.operation_id
    WHERE b.id=NEW.block_id AND r.id=NEW.revision_id AND b.space_id=NEW.space_id
      AND b.xmin::text=current_xid AND r.xmin::text=current_xid
      AND r.parent_revision_id IS NULL AND r.author_id=o.author_id AND r.reason=o.reason
      AND NOT EXISTS(SELECT 1 FROM public.block_revision prior_revision WHERE prior_revision.block_id=b.id AND prior_revision.id<>r.id))
  THEN RAISE EXCEPTION 'lineage output must be new owned content' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.b3_lineage_new_member() OWNER TO learning_admin;

