-- Name: p0c2_cancel_job(uuid); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_cancel_job(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.job AS j
       SET status = 'cancelled', lease_token = NULL, lease_expires_at = NULL,
           next_attempt_at = NULL, output_digest = NULL
     WHERE j.id = p_job_id AND j.status IN ('queued', 'running', 'retry_wait');
    RETURN FOUND;
END $$;


ALTER FUNCTION public.p0c2_cancel_job(p_job_id uuid) OWNER TO learning_admin;

--
-- Name: p0c2_check_dispatch(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_check_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'job_outbox' THEN
        IF NEW.dispatched_at IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.job j
             WHERE j.outbox_id = NEW.id AND j.idempotency_key = NEW.business_key
        ) THEN
            RAISE EXCEPTION 'dispatched event has no job' USING ERRCODE = '23514';
        END IF;
    ELSIF NOT EXISTS (
        SELECT 1 FROM public.job_outbox e
         WHERE e.id = NEW.outbox_id AND e.dispatched_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'job has no dispatched event' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION public.p0c2_check_dispatch() OWNER TO learning_admin;

--
-- Name: p0c2_checkpoint_job(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_checkpoint_job(p_job_id uuid, p_token uuid, p_checkpoint jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF jsonb_typeof(p_checkpoint) IS DISTINCT FROM 'object'
       OR octet_length(p_checkpoint::text) > 16384 THEN
        RAISE EXCEPTION 'invalid checkpoint' USING ERRCODE = '22023';
    END IF;
    UPDATE public.job AS j SET checkpoint = p_checkpoint
     WHERE j.id = p_job_id AND j.status = 'running' AND j.lease_token = p_token
       AND j.lease_expires_at > clock_timestamp();
    RETURN FOUND;
END $$;


