--
-- Name: p0c2_claim_job(uuid, bigint); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_claim_job(p_job_id uuid, p_lease_ms bigint) RETURNS TABLE(job_id uuid, token uuid, attempts integer, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF p_lease_ms IS NULL OR p_lease_ms NOT BETWEEN 1 AND 300000 THEN
        RAISE EXCEPTION 'invalid lease request' USING ERRCODE = '22023';
    END IF;

    UPDATE public.job AS j
       SET status = 'failed', lease_token = NULL, lease_expires_at = NULL,
           last_error_class = 'lease_expired', output_digest = NULL
     WHERE j.id = p_job_id AND EXISTS (SELECT 1 FROM public.job_outbox e WHERE e.id=j.outbox_id AND e.event_type='asset_integrity_requested') AND j.status = 'running'
       AND j.lease_expires_at <= clock_timestamp() AND j.attempt_count >= 3;

    RETURN QUERY
    UPDATE public.job AS j
       SET status = 'running', attempt_count = j.attempt_count + 1,
           lease_token = pg_catalog.gen_random_uuid(),
           lease_expires_at = clock_timestamp() + p_lease_ms * interval '1 millisecond',
           next_attempt_at = NULL, last_error_class = NULL,
           output_digest = NULL
     WHERE j.id = p_job_id AND EXISTS (SELECT 1 FROM public.job_outbox e WHERE e.id=j.outbox_id AND e.event_type='asset_integrity_requested') AND j.attempt_count < 3
       AND (j.status = 'queued'
         OR (j.status = 'retry_wait' AND j.next_attempt_at <= clock_timestamp())
         OR (j.status = 'running' AND j.lease_expires_at <= clock_timestamp()))
     RETURNING j.id, j.lease_token, j.attempt_count, j.lease_expires_at;
END $$;


ALTER FUNCTION public.p0c2_claim_job(p_job_id uuid, p_lease_ms bigint) OWNER TO learning_admin;

--
-- Name: p0c2_complete_asset_job(uuid, uuid, uuid, uuid, uuid, uuid, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_complete_asset_job(p_job_id uuid, p_token uuid, p_space_id uuid, p_block_id uuid, p_revision_id uuid, p_asset_id uuid, p_sha256 text, p_byte_size bigint, p_media_type text, p_digest text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE inserted integer;
BEGIN
    IF p_job_id IS NULL OR p_token IS NULL OR p_space_id IS NULL
       OR p_block_id IS NULL OR p_revision_id IS NULL OR p_asset_id IS NULL
       OR p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'
       OR p_byte_size IS NULL OR p_byte_size < 0
       OR p_media_type IS NULL OR char_length(p_media_type) NOT BETWEEN 1 AND 200
       OR p_digest IS NULL OR p_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'invalid asset result' USING ERRCODE = '22023';
    END IF;
    -- A caller cannot substitute a different space, exact revision, asset,
    -- fingerprint, or media identity for the immutable business event.
    IF NOT EXISTS (
        SELECT 1 FROM public.job AS j
        JOIN public.job_outbox AS e ON e.id = j.outbox_id
        JOIN public.block_asset_use AS u
          ON (u.space_id, u.block_id, u.revision_id)
           = (p_space_id, p_block_id, p_revision_id)
        JOIN public.asset AS a
          ON (a.space_id, a.id) = (u.space_id, u.asset_id)
        JOIN public.space_grant AS g
          ON g.space_id = u.space_id AND g.actor_id = e.actor_id
        WHERE j.id = p_job_id AND j.status = 'running'
          AND e.event_type = 'asset_integrity_requested'
          AND e.payload_version = 1 AND e.processor_version = 1
          AND e.payload->>'space_id' = p_space_id::text
          AND e.payload->>'block_id' = p_block_id::text
          AND e.payload->>'revision_id' = p_revision_id::text
          AND e.payload->>'actor_id' = e.actor_id::text
          AND a.id = p_asset_id AND a.status = 'ready'
          AND a.sha256 = p_sha256 AND a.byte_size = p_byte_size
          AND a.media_type = p_media_type
    ) THEN
        RETURN false;
    END IF;
    IF NOT public.p0c2_succeed_job(p_job_id, p_token, p_digest) THEN
        RETURN false;
    END IF;
    INSERT INTO public.asset_integrity_result (
        job_id, idempotency_key, processor_version, result_version,
        space_id, block_id, revision_id, asset_id,
        sha256, byte_size, media_type, output_digest
    )
    SELECT j.id, j.idempotency_key, e.processor_version, 1,
           p_space_id, p_block_id, p_revision_id, p_asset_id,
           p_sha256, p_byte_size, p_media_type, p_digest
      FROM public.job AS j
      JOIN public.job_outbox AS e ON e.id = j.outbox_id
     WHERE j.id = p_job_id;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted <> 1 THEN
        RAISE EXCEPTION 'asset result insert did not affect one row'
            USING ERRCODE = '23514';
    END IF;
    RETURN true;
END $_$;


ALTER FUNCTION public.p0c2_complete_asset_job(p_job_id uuid, p_token uuid, p_space_id uuid, p_block_id uuid, p_revision_id uuid, p_asset_id uuid, p_sha256 text, p_byte_size bigint, p_media_type text, p_digest text) OWNER TO learning_admin;

--
-- Name: p0c2_fail_job(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_fail_job(p_job_id uuid, p_token uuid, p_error_class text, p_retryable boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF ((p_error_class = 'transient_storage' AND p_retryable IS TRUE)
        OR (p_error_class = 'invalid_input' AND p_retryable IS FALSE)) IS NOT TRUE THEN
        RAISE EXCEPTION 'invalid failure class' USING ERRCODE = '22023';
    END IF;
    UPDATE public.job AS j
       SET status = CASE WHEN p_retryable AND j.attempt_count < 3
                         THEN 'retry_wait' ELSE 'failed' END,
           lease_token = NULL, lease_expires_at = NULL,
           next_attempt_at = CASE WHEN p_retryable AND j.attempt_count < 3
                THEN clock_timestamp() + CASE j.attempt_count
                    WHEN 1 THEN interval '1 second' ELSE interval '2 seconds' END
                ELSE NULL END,
           last_error_class = p_error_class, output_digest = NULL
     WHERE j.id = p_job_id AND j.status = 'running' AND j.lease_token = p_token
       AND j.lease_expires_at > clock_timestamp();
    RETURN FOUND;
END $$;


ALTER FUNCTION public.p0c2_fail_job(p_job_id uuid, p_token uuid, p_error_class text, p_retryable boolean) OWNER TO learning_admin;

--
-- Name: p0c2_guard_asset_integrity_result(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_guard_asset_integrity_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'asset integrity result is immutable' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.job AS j
         WHERE j.id = NEW.job_id AND j.idempotency_key = NEW.idempotency_key
           AND j.status = 'succeeded' AND j.output_digest = NEW.output_digest
    ) THEN
        RAISE EXCEPTION 'asset result does not match completed job'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.p0c2_guard_asset_integrity_result() OWNER TO learning_admin;

--
-- Name: p0c2_guard_job(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_guard_job() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE is_snapshot boolean; new_state text; old_state text;
BEGIN
    SELECT e.event_type='snapshot_export_requested' INTO is_snapshot FROM public.job_outbox e WHERE e.id=NEW.outbox_id;
    IF is_snapshot IS TRUE THEN
        IF TG_OP='INSERT' THEN
            NEW.id := NEW.outbox_id;
            IF NEW.status='queued' THEN NEW.status := 'snapshot_queued'; END IF;
        END IF;
        IF NEW.status NOT IN ('snapshot_queued','snapshot_running','snapshot_retry_wait','succeeded','failed','cancelled') THEN
            RAISE EXCEPTION 'wrong snapshot job state family' USING ERRCODE='23514';
        END IF;
        new_state := replace(NEW.status,'snapshot_','');
        IF TG_OP='UPDATE' THEN old_state := replace(OLD.status,'snapshot_',''); END IF;
    ELSE
        IF NEW.status NOT IN ('queued','running','retry_wait','succeeded','failed','cancelled') THEN
            RAISE EXCEPTION 'wrong asset job state family' USING ERRCODE='23514';
        END IF;
        new_state := NEW.status;
        IF TG_OP='UPDATE' THEN old_state := OLD.status; END IF;
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF new_state <> 'queued' OR NEW.attempt_count <> 0 THEN
            RAISE EXCEPTION 'job must start queued' USING ERRCODE = '23514';
        END IF;
    ELSE
        IF NEW.id IS DISTINCT FROM OLD.id
           OR NEW.outbox_id IS DISTINCT FROM OLD.outbox_id
           OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
           OR NEW.created_at IS DISTINCT FROM OLD.created_at
           OR old_state IN ('succeeded','failed','cancelled')
           OR (old_state = 'queued' AND new_state NOT IN ('running','cancelled'))
           OR (old_state = 'running' AND new_state NOT IN
               ('running','retry_wait','succeeded','failed','cancelled'))
           OR (old_state = 'retry_wait' AND new_state NOT IN
               ('running','cancelled'))
           OR (old_state IN ('queued','retry_wait') AND new_state = 'running'
               AND NEW.attempt_count <> OLD.attempt_count + 1)
           OR (old_state = 'running' AND new_state = 'running'
               AND ((NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token
                        AND NEW.attempt_count <> OLD.attempt_count)
                   OR (NEW.lease_token IS DISTINCT FROM OLD.lease_token
                        AND (OLD.lease_expires_at > clock_timestamp()
                             OR NEW.attempt_count <> OLD.attempt_count + 1))))
           OR (new_state <> 'running' AND NEW.attempt_count <> OLD.attempt_count) THEN
            RAISE EXCEPTION 'invalid job transition' USING ERRCODE = '23514';
        END IF;
        NEW.updated_at := clock_timestamp();
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.p0c2_guard_job() OWNER TO learning_admin;

--
-- Name: p0c2_guard_job_outbox(); Type: FUNCTION; Schema: public; Owner: learning_admin
--

CREATE FUNCTION public.p0c2_guard_job_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.dispatched_at IS NOT NULL THEN
            RAISE EXCEPTION 'new job event is already dispatched' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.business_key IS DISTINCT FROM OLD.business_key
       OR NEW.event_type IS DISTINCT FROM OLD.event_type
       OR NEW.payload_version IS DISTINCT FROM OLD.payload_version
       OR NEW.payload IS DISTINCT FROM OLD.payload
       OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
       OR NEW.processor_version IS DISTINCT FROM OLD.processor_version
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR (OLD.dispatched_at IS NOT NULL
           AND NEW.dispatched_at IS DISTINCT FROM OLD.dispatched_at) THEN
        RAISE EXCEPTION 'job outbox history is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.p0c2_guard_job_outbox() OWNER TO learning_admin;

