--
-- Name: system_lineage; Type: VIEW; Schema: public; Owner: learning_admin
--

CREATE VIEW public.system_lineage AS
 SELECT o.id AS operation_id,
        CASE o.operation
            WHEN 'derive'::text THEN 'derived_from'::text
            WHEN 'split'::text THEN 'split_from'::text
            ELSE 'merged_from'::text
        END AS type,
    r.block_id AS from_block_id,
    r.revision_id AS from_revision_id,
    i.block_id AS to_block_id,
    i.revision_id AS to_revision_id,
    r."position" AS output_position,
    i."position" AS input_position
   FROM ((public.lineage_operation o
     JOIN public.lineage_input i ON ((i.operation_id = o.id)))
     JOIN public.lineage_output r ON ((r.operation_id = o.id)));


ALTER VIEW public.system_lineage OWNER TO learning_admin;

